104		iowrite32(INT_ENABLE, info->priv + INT_ENABLE_ADDR);
105		iowrite8(INT_MASK_ALL, info->priv + INT_MASK_ADDR);
106		if (!(ioread8(info->priv + INTA_DRVR_ADDR)
